/*
 * Arduino Nano -> Browser via Serial (JSON)
 * IMU: MPU-6050 (I2C: SDA=A4, SCL=A5)
 * Микрофон: MAX9814 или аналоговый (A0)
 */

#include <Wire.h>
#include <MPU6050.h>

MPU6050 mpu;

int16_t ax, ay, az, gx, gy, gz;
const int micPin = A0;
int micValue = 0;

unsigned long lastSend = 0;
const int sendInterval = 50; // 20 Гц

void setup() {
  Serial.begin(115200);
  Wire.begin();
  mpu.initialize();

  if (mpu.testConnection()) {
    Serial.println("{\"status\":\"ok\"}");
  } else {
    Serial.println("{\"status\":\"error\",\"msg\":\"MPU6050 not found\"}");
  }
  delay(500);
}

void loop() {
  if (millis() - lastSend >= sendInterval) {
    lastSend = millis();

    mpu.getMotion6(&ax, &ay, &az, &gx, &gy, &gz);
    micValue = analogRead(micPin);

    Serial.print("{\"ax\":"); Serial.print(ax);
    Serial.print(",\"ay\":"); Serial.print(ay);
    Serial.print(",\"az\":"); Serial.print(az);
    Serial.print(",\"gx\":"); Serial.print(gx);
    Serial.print(",\"gy\":"); Serial.print(gy);
    Serial.print(",\"gz\":"); Serial.print(gz);
    Serial.print(",\"mic\":"); Serial.print(micValue);
    Serial.println("}");
  }
}
